 * Dosya      : hosting/php/tests/PersonalShoppingTest.php
 * Açıklama   : Misafir favorisi, özel liste, karşılaştırma, sürüm ve toplu sepet kuralları.
 */
declare(strict_types=1);
require_once __DIR__.'/TestDatabase.php';
use PHPUnit\Framework\TestCase;
use Sexogate\{Fixtures,Principal,PersonalShopping,Cart,ShoppingCart,RuleViolation,Auth};
final class PersonalShoppingTest extends TestCase
{
    private function shop():array
    {self::assertTrue(class_exists(PersonalShopping::class),'Personal shopping service is not implemented.');$f=new TestDatabase();$x=new Fixtures($f->db,$f->config);$x->policies();$x->catalog(new Principal('admin','admin',true));return [$f,new PersonalShopping($f->db,$f->config),bin2hex(random_bytes(32))];}
    public function testAnonymousFavoritesAndListsAreOwnedAndVersioned():void
    {[$f,$s,$token]=$this->shop();$id=$f->db->one("SELECT id FROM products WHERE slug='saten-bag-detayi'")['id'];$a=$s->command($token,['action'=>'favorite','productId'=>$id,'selected'=>true,'version'=>0]);self::assertSame([$id],$a['favorites']);self::assertSame([],$s->get(bin2hex(random_bytes(32)))['favorites']);$b=$s->command($token,['action'=>'list-create','name'=>'İç Giyim · Şişli','version'=>$a['version']]);self::assertSame('İç Giyim · Şişli',$b['lists'][0]['name']);$list=$b['lists'][0]['id'];$c=$s->command($token,['action'=>'list-add','listId'=>$list,'productIds'=>[$id,$id],'version'=>$b['version']]);self::assertSame([$id],$c['lists'][0]['items']);try{$s->command($token,['action'=>'list-remove','listId'=>$list,'version'=>$b['version']]);self::fail('Stale state changed the list');}catch(RuleViolation $e){self::assertSame('SHOPPING_CHANGED',$e->rule);}self::assertCount(1,$s->get($token)['lists']);}
    public function testBulkAddPreservesExistingQuantityAndRejectsUnownedList():void
    {[$f,$s,$token]=$this->shop();$p=$f->db->one("SELECT p.id,v.id variant FROM products p JOIN variants v ON v.product_id=p.id WHERE p.slug='saten-bag-detayi'");$a=$s->command($token,['action'=>'favorite','productId'=>$p['id'],'selected'=>true,'version'=>0]);(new ShoppingCart($f->db,$f->config))->command($token,['action'=>'add','variantId'=>$p['variant'],'quantity'=>3]);$s->addToCart($token,['source'=>'favorites','productIds'=>[$p['id']],'version'=>$a['version']]);self::assertSame(3,(new Cart($f->db,$f->config))->get($token)['items'][0]['quantity']);$l=$s->command($token,['action'=>'list-create','name'=>'Özel','version'=>$a['version']]);try{$s->command(bin2hex(random_bytes(32)),['action'=>'list-add','listId'=>$l['lists'][0]['id'],'productIds'=>[$p['id']],'version'=>0]);self::fail('Other device list was changed');}catch(RuleViolation $e){self::assertSame('LIST_NOT_FOUND',$e->rule);}}
    public function testLimitsAndBadNamesCannotBeSilentlyTruncated():void
    {[$f,$s,$token]=$this->shop();$state=$s->get($token);for($i=0;$i<20;$i++)$state=$s->command($token,['action'=>'list-create','name'=>'Liste '.($i+1),'version'=>$state['version']]);try{$s->command($token,['action'=>'list-create','name'=>'Fazla','version'=>$state['version']]);self::fail('Twenty first list accepted');}catch(RuleViolation $e){self::assertSame('LIST_LIMIT',$e->rule);}try{$s->command($token,['action'=>'list-rename','listId'=>$state['lists'][0]['id'],'name'=>"<script>\nGizli",'version'=>$state['version']]);self::fail('Control character accepted');}catch(RuleViolation $e){self::assertSame('INVALID_LIST_NAME',$e->rule);}self::assertCount(20,$s->get($token)['lists']);}
    public function testComparisonAndListItemAndTotalLimitsAreAtomic():void
    {[$f,$s,$token]=$this->shop();$ids=[];for($n=0;$n<101;$n++){$id='private-limit-'.$n;$ids[]=$id;$f->db->execute("INSERT INTO products(id,slug,name,name_en,category,image,status,fixture) VALUES(?,?,?,?,'ic-giyim','/media/atelier-01.svg','published',true)",[$id,$id,'Ölçü '.$n,'Measurement '.$n]);}$state=$s->get($token);foreach(array_slice($ids,0,4) as $id)$state=$s->command($token,['action'=>'compare','productId'=>$id,'selected'=>true,'version'=>$state['version']]);try{$s->command($token,['action'=>'compare','productId'=>$ids[4],'selected'=>true,'version'=>$state['version']]);self::fail('Fifth comparison accepted');}catch(RuleViolation $e){self::assertSame('COMPARE_LIMIT',$e->rule);}self::assertCount(4,$s->get($token)['compare']);$state=$s->command($token,['action'=>'list-create','name'=>'Ölçü','productIds'=>array_slice($ids,0,100),'version'=>$state['version']]);try{$s->command($token,['action'=>'list-add','listId'=>$state['lists'][0]['id'],'productIds'=>[$ids[100]],'version'=>$state['version']]);self::fail('Hundred first item accepted');}catch(RuleViolation $e){self::assertSame('LIST_ITEM_LIMIT',$e->rule);}for($n=1;$n<10;$n++)$state=$s->command($token,['action'=>'list-create','name'=>'Liste '.$n,'productIds'=>array_slice($ids,0,100),'version'=>$state['version']]);try{$s->command($token,['action'=>'list-create','name'=>'Fazla','productIds'=>[$ids[0]],'version'=>$state['version']]);self::fail('Total exceeded 1000');}catch(RuleViolation $e){self::assertSame('LIST_TOTAL_LIMIT',$e->rule);}self::assertCount(10,$s->get($token)['lists']);}
    public function testAccountTransferRequiresConsentAndBothVersionsAndDoesNotLeakToAnotherUser():void
    {[$f,$s,$guest]=$this->shop();foreach(['alpha','beta'] as $u)$f->db->execute('INSERT INTO `user`(id,name,email,emailVerified,role) VALUES(?,?,?,true,?)',[$u,'Müşteri '.$u,$u.'@example.invalid','customer']);$id=$f->db->one('SELECT id FROM products LIMIT 1')['id'];$saved=$s->command($guest,['action'=>'favorite','productId'=>$id,'selected'=>true,'version'=>0]);$account=bin2hex(random_bytes(32));(new Sexogate\Customers($f->db,$f->config))->mergeCart($guest,$account,'alpha');$key=PersonalShopping::guestKey($guest);$preview=$s->transferPreview($key,$account,'alpha');self::assertSame([],$preview['target']['favorites']);try{$s->transfer($key,$account,'alpha',['version'=>0,'sourceVersion'=>$saved['version']]);self::fail('Transfer without consent');}catch(RuleViolation $e){self::assertSame('TRANSFER_CONSENT_REQUIRED',$e->rule);}try{$s->transfer($key,$account,'alpha',['confirmed'=>true,'version'=>0,'sourceVersion'=>0]);self::fail('Stale source transferred');}catch(RuleViolation $e){self::assertSame('SHOPPING_CHANGED',$e->rule);}$result=$s->transfer($key,$account,'alpha',['confirmed'=>true,'version'=>0,'sourceVersion'=>$saved['version']]);self::assertSame([$id],$result['favorites']);self::assertSame([],$s->get($guest)['favorites']);self::assertSame([],$s->get(bin2hex(random_bytes(32)),'beta')['favorites']);try{$s->get($account,'beta');self::fail('Other account cart used');}catch(RuleViolation $e){self::assertSame(404,$e->status);}$f->db->execute('UPDATE shopping_states SET expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE owner_key=?',[$key]);$old=$s->get($guest);self::assertSame([],$old['favorites']);$new=$s->command($guest,['action'=>'favorite','productId'=>$id,'selected'=>true,'version'=>$old['version']]);self::assertGreaterThan($old['version'],$new['version']);}
    public function testWorkerErasesExpiredGuestPreferencesAndKeepsVersionsMonotonic():void
    {[$f,$s,$token]=$this->shop();$id=$f->db->one('SELECT id FROM products LIMIT 1')['id'];$state=$s->command($token,['action'=>'favorite','productId'=>$id,'selected'=>true,'version'=>0]);$key=PersonalShopping::guestKey($token);$f->db->execute('UPDATE shopping_states SET expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE owner_key=?',[$key]);(new Sexogate\Worker($f->db,$f->config))->tick();$row=$f->db->one('SELECT version,payload FROM shopping_states WHERE owner_key=?',[$key]);self::assertSame([] ,json_decode($row['payload'],true)['favorites']);self::assertGreaterThan($state['version'],(int)$row['version']);$version=(int)$row['version'];(new Sexogate\Worker($f->db,$f->config))->tick();self::assertSame($version,(int)$f->db->one('SELECT version FROM shopping_states WHERE owner_key=?',[$key])['version']);$this->expectException(RuleViolation::class);$s->command($token,['action'=>'favorite','productId'=>$id,'selected'=>true,'version'=>$state['version']]);}
}
